 function errorText(e){if(e?.message?.includes('Authentication > Users'))return 'Email belum terdaftar. Gunakan Buat Akun Baru atau minta pengguna mendaftar dari halaman login.';if(e?.code==='40001')return 'PO sudah berubah di perangkat lain. Tutup formulir, muat data terbaru, lalu ulangi tindakan.';if(['42501','22023','23514','23503','23505'].includes(e?.code))return e.message||'Data atau tindakan belum valid.';return 'Koneksi ke server gagal. Data formulir tetap tersedia; periksa koneksi dan coba lagi.'}
 function gate(title,sub,html=''){closeChat();$('#chat-fab')?.remove();$('#po-fab')?.remove();closeMenu();document.querySelector('.header-menu')?.remove();$('#sidebar').innerHTML='<div class="logo"><img class="logo-icon brand-logo" src="assets/logo.png" alt="Logo Kedai UPU PO" width="52" height="52"><b>Kedai UPU PO</b></div>';$('#bottom').innerHTML='';$('#main').innerHTML=`<section class="panel auth-panel"><img class="auth-brand" src="assets/logo.png" alt="Logo Kedai UPU PO" width="160" height="160"><span class="eyebrow">PURCHASING ↔ SALES SUPPLIER</span><h1>${esc(title)}</h1><p class="sub">${esc(sub)}</p>${html}</section>`}
 function loginScreen(){gate('Masuk ke Kedai UPU','Satu tempat untuk menerbitkan PO, konfirmasi supplier, dan memantau pengiriman.',`<form onsubmit="event.preventDefault();PO.login(this)"><div class="form-group"><label for="email">Email</label><input id="email" name="email" type="email" autocomplete="username" required></div><div class="form-group"><label for="password">Kata sandi</label><input id="password" name="password" type="password" autocomplete="current-password" required></div><p id="login-error" class="form-error" role="alert"></p><button class="btn primary" type="submit">Masuk</button></form><button class="text-link" onclick="PO.registrationForm()">Belum punya akun? Daftar di sini</button><p class="sub">Hubungi pengelola jika lupa kata sandi.</p>`)}
 function icon(name){const paths={monthly:'M4 5h16v16H4zM4 9h16M8 3v4M16 3v4M8 17l3-3 3 2 3-4',edit:'M16 3l5 5M4 16L16 4a3 3 0 0 1 4 4L8 20H4v-4z',trash:'M3 6h18M9 6V3h6v3M5 6l1 15h12l1-15M10 10v7M14 10v7',chat:'M4 4h16v12H9l-5 4V4zM8 8h8M8 12h5',dashboard:'M3 3h7v7H3zM14 3h7v7h-7zM3 14h7v7H3zM14 14h7v7h-7z',orders:'M8 3H5v18h14V3h-3M9 2h6v4H9zM8 11h8M8 15h6',create:'M12 5v14M5 12h14',notifications:'M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4',menu:'M4 6h16M4 12h16M4 18h16',account:'M16 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0M4 21v-2a8 8 0 0 1 16 0v2',new:'M12 3l2.8 5.7L21 9.6l-4.5 4.4 1 6.2-5.5-2.9-5.5 2.9 1-6.2L3 9.6l6.2-.9z',history:'M3 11a9 9 0 1 1 3 7M3 4v7h7M12 7v5l3 2',suppliers:'M3 21V7l9-4 9 4v14M8 21v-7h8v7M8 8h1M15 8h1',products:'M3 7l9-4 9 4v10l-9 4-9-4zM3 7l9 5 9-5M12 12v9',users:'M16 21v-2a5 5 0 0 0-10 0v2M14 7a3 3 0 1 1-6 0 3 3 0 0 1 6 0M18 4a3 3 0 0 1 0 6M20 21v-2a5 5 0 0 0-3-4',import:'M12 3v12M7 10l5 5 5-5M4 16v5h16v-5',arrow:'M5 12h14M14 7l5 5-5 5'};return '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="'+(paths[name]||paths.import)+'"/></svg>'}
 function closeMenu(){const drawer=document.querySelector('#menu-drawer');if(drawer?.open)drawer.close()}
 function installDrawerSwipe(drawer){
  let gesture=null,suppressUntil=0;
  drawer.addEventListener('touchstart',event=>{gesture=null;if(!drawer.open||event.touches.length!==1)return;const t=event.touches[0];gesture={id:t.identifier,x:t.clientX,y:t.clientY,time:Date.now(),horizontal:false}},{passive:true});
  drawer.addEventListener('touchmove',event=>{if(!gesture)return;if(event.touches.length!==1){gesture=null;return}const t=event.touches[0];if(t.identifier!==gesture.id){gesture=null;return}const dx=t.clientX-gesture.x,dy=Math.abs(t.clientY-gesture.y);if(!gesture.horizontal&&dy>12&&dy>=Math.abs(dx)){gesture=null;return}if(dx< -16&&Math.abs(dx)>dy*1.5)gesture.horizontal=true;if(gesture.horizontal&&event.cancelable)event.preventDefault()},{passive:false});
  drawer.addEventListener('touchcancel',()=>{gesture=null},{passive:true});
  drawer.addEventListener('touchend',event=>{const g=gesture;gesture=null;if(!g||!drawer.open||event.touches.length)return;const t=[...event.changedTouches].find(t=>t.identifier===g.id);if(!t)return;const dx=t.clientX-g.x,dy=Math.abs(t.clientY-g.y);if(dx<=-72&&Math.abs(dx)>dy*1.5&&Date.now()-g.time<=900){suppressUntil=Date.now()+350;closeMenu()}},{passive:true});
  drawer.addEventListener('click',event=>{if(Date.now()<suppressUntil){event.preventDefault();event.stopImmediatePropagation()}},true);
 }
