  drawer.innerHTML='<div class="drawer-heading"><img src="assets/logo.png" alt="" width="48" height="48"><div><b>Kedai UPU PO</b><small>'+esc(roles[S.data.me.role])+'</small></div><button class="drawer-close" aria-label="Tutup menu" onclick="PO.closeMenu()">&#215;</button></div><nav aria-label="Navigasi aplikasi">'+navigation.map(([id,_,title])=>'<button class="drawer-link '+(S.page===id?'active':'')+'" onclick="PO.go(\''+id+'\')">'+icon(id)+'<span>'+title+'</span></button>').join('')+'</nav><p class="drawer-account">'+esc(S.data.me.name)+'</p>';
