 function desktopTable(list){return list.length?`<div class="table-wrap"><table><thead><tr><th>Nomor PO / Tanggal</th><th>Supplier</th><th>Status</th><th>Estimasi antar</th><th>Barang</th></tr></thead><tbody>${list.map(o=>`<tr class="clickable" tabindex="0" onclick="PO.open('${o.id}')" onkeydown="if(event.key==='Enter')PO.open('${o.id}')"><td><strong>${esc(o.number)}</strong><small>${date(o.order_date)}</small></td><td>${esc(supplier(o.supplier_id)?.name||o.supplier_id)}</td><td>${badge(o.status)}${stockBadge(o)}${M.late(o)?badge('Terlambat'):''}</td><td>${o.stock_unavailable?'Tertunda - stok masuk '+date(o.stock_eta):o.eta?date(o.eta):'—'}</td><td>${items(o.id).length} item · ${qtyLocked(o)?'Qty terkunci':items(o.id).reduce((s,i)=>s+i.qty,0)+' qty'}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty"><h2>Belum ada PO</h2><p>PO yang sesuai akan tampil di sini.</p></div>'}
