 function matchesStatus(o,code){return code==='all'||(code==='active'?!['Draft','Completed','Cancelled'].includes(o.status):code==='late'?M.late(o):code==='new'?o.my_confirmed!==true&&!['Draft','Cancelled'].includes(o.status):o.status===code)}
